#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GeneratedIntrinsicTarget {
    pub marker: &'static str,
    pub id: &'static str,
    pub abi_id: &'static str,
    pub dialect_op: &'static str,
    pub variant: GeneratedIntrinsicVariant,
    pub requirement: GeneratedTargetRequirement,
    pub backend_requirements: &'static [GeneratedBackendRequirement],
    pub selections: &'static [GeneratedSelectionAlternative],
    pub llvm: Option<GeneratedLlvmFacts>,
}

impl GeneratedHardwareTarget {
    pub fn contract_for_selector(
        self,
        name: &str,
        value: &str,
    ) -> Option<&'static GeneratedTargetContract> {
        let Self::TargetMatrix { contracts } = self else {
            return None;
        };
        let mut matching = contracts.iter().filter(|contract| {
            matches!(contract.selectors, [binding] if binding.name == name && binding.value == value)
        });
        let contract = matching.next()?;
        if matching.next().is_some() {
            None
        } else {
            Some(contract)
        }
    }
}

impl GeneratedIntrinsicTarget {
    pub fn requirement_for_backend(
        &self,
        backend: GeneratedIntrinsicBackend,
    ) -> GeneratedTargetRequirement {
        self.backend_requirements
            .iter()
            .find(|entry| entry.backend == backend)
            .map(|entry| entry.requirement)
            .unwrap_or(self.requirement)
    }

    pub fn target_contract_for_backend_selector(
        &self,
        backend: GeneratedIntrinsicBackend,
        name: &str,
        value: &str,
    ) -> Option<&'static GeneratedTargetContract> {
        self.requirement_for_backend(backend)
            .hardware
            .contract_for_selector(name, value)
    }
}

